mapper.select:
SELECT 
FROM trip_plans
WHERE user_id = #{userId}
ORDER BY updated_at DESC, trip_plan_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT 
FROM trip_plans
WHERE trip_plan_id = #{tripPlanId}
  AND user_id = #{userId}

mapper.update:
UPDATE trip_plans
SET
    title = #{title},
    description = #{description},
    start_date = #{startDate},
    end_date = #{endDate}
WHERE trip_plan_id = #{id}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM trip_plans
WHERE trip_plan_id = #{tripPlanId}
  AND user_id = #{userId}

mapper.update:
UPDATE trip_plan_places
SET
    visit_date = #{place.visitDate},
    memo = #{place.memo}
WHERE trip_plan_id = #{tripPlanId}
  AND trip_plan_place_id = #{place.id}

UPDATE trip_plan_places
SET visit_order = #{visitOrder}
WHERE trip_plan_id = #{tripPlanId}
  AND trip_plan_place_id = #{tripPlanPlaceId}

mapper.delete:
DELETE FROM trip_plan_places
WHERE trip_plan_id = #{tripPlanId}
  AND trip_plan_place_id = #{tripPlanPlaceId}

mapper.select:
SELECT COALESCE(MAX(visit_order), 0) + 1
FROM trip_plan_places
WHERE trip_plan_id = #{tripPlanId}

SELECT COUNT(*)
FROM trip_plan_places
WHERE trip_plan_id = #{tripPlanId}

SELECT EXISTS (
    SELECT 1
    FROM trip_plan_places
    WHERE trip_plan_id = #{tripPlanId}
      AND place_id = #{placeId}
)
